<?php
namespace App\Game;
final class JobService { public const JOBS=['courier'=>['title'=>'🛵 پیک','min_level'=>1,'pay'=>150,'energy'=>15,'xp'=>40],'employee'=>['title'=>'💼 کارمند','min_level'=>2,'pay'=>400,'energy'=>20,'xp'=>70],'dev'=>['title'=>'💻 برنامه‌نویس','min_level'=>4,'pay'=>1200,'energy'=>25,'xp'=>120],'sup'=>['title'=>'🧷 سرپرست','min_level'=>6,'pay'=>2200,'energy'=>25,'xp'=>150],'manager'=>['title'=>'📊 مدیر','min_level'=>9,'pay'=>4000,'energy'=>30,'xp'=>200],'ceo'=>['title'=>'👔 مدیرعامل','min_level'=>14,'pay'=>9000,'energy'=>35,'xp'=>300]];
 public static function availableJobs(array $user):array{$o=[];foreach(self::JOBS as $k=>$j)$o[$k]=['locked'=>(int)$user['level']<(int)$j['min_level'],...$j];return $o;}
 public static function work(array $user):array{$key=(string)($user['job']??'');if(!isset(self::JOBS[$key]))return['error'=>'no_job'];$j=self::JOBS[$key];if((int)$user['energy']<(int)$j['energy'])return['error'=>'not_enough_energy'];$pay=(int)round($j['pay']*random_int(85,125)/100);PlayerService::update((int)$user['id'],['energy'=>max(0,(int)$user['energy']-$j['energy'])]);EconomyService::earn($user,$pay,'دستمزد: '.$j['title']);MissionService::progress($user,'work_count',1);return['pay'=>$pay,'xp'=>$j['xp'],'energy'=>$j['energy']];}}
